var inversions = 0
fun mergeSort(values: IntArray, l: Int, r: Int) {
    val m = (l + r) / 2
    mergeSort(values, l, m)
    mergeSort(values, m + 1, r)
    var i = l
    var j = m + 1
    while (i <= m && j <= r) {
        if (values[i] < values[j]) {
            merged.add(values[i++])
        } else {
            merged.add(values[j++])
            inversions += m - i + 1
        }
    }
    println("merge [$l..$r]: ${merged.joinToString(" ")}")
